-- PRACTICE DATA ONLY. MariaDB 10.6+; do not run on production.

CREATE DATABASE IF NOT EXISTS billing_practice CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE billing_practice;

DROP TABLE IF EXISTS DISCOUNT_RESULT;

DROP TABLE IF EXISTS BILL;

DROP TABLE IF EXISTS CHARGE_TEMP;

DROP TABLE IF EXISTS KB_DISCOUNT_INFO;

DROP TABLE IF EXISTS CTRT_CHANGE_HIST;

DROP TABLE IF EXISTS DISCOUNT_POLICY;

DROP TABLE IF EXISTS PRODUCT_INFO;

DROP TABLE IF EXISTS CTRT_INFO;

CREATE TABLE CTRT_INFO (
 CTRT_ID VARCHAR(12) PRIMARY KEY, ACENO VARCHAR(16) NOT NULL UNIQUE,
 PROD_CD VARCHAR(12) NOT NULL, ORDER_TP VARCHAR(12) NOT NULL,
 CTRT_STATUS VARCHAR(12) NOT NULL, JOIN_DT DATE NOT NULL,
 END_DT DATE NULL, LAST_CHANGE_DT DATE NULL,
 KEY IX_CTRT_PROD (PROD_CD), KEY IX_CTRT_ORDER (ORDER_TP)
) ENGINE=InnoDB;

CREATE TABLE PRODUCT_INFO (
 PROD_CD VARCHAR(12) PRIMARY KEY, PROD_NM VARCHAR(100) NOT NULL,
 BASE_FEE DECIMAL(13,2) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE DISCOUNT_POLICY (
 FTCR_CD VARCHAR(16) PRIMARY KEY, FTCR_NM VARCHAR(80) NOT NULL,
 DISC_TYPE VARCHAR(10) NOT NULL, DISC_VALUE DECIMAL(13,2) NOT NULL,
 ELIG_PROD_CD VARCHAR(12) NOT NULL, USE_YN CHAR(1) NOT NULL DEFAULT 'Y'
) ENGINE=InnoDB;

CREATE TABLE CTRT_CHANGE_HIST (
 HIST_ID INT PRIMARY KEY, CTRT_ID VARCHAR(12) NOT NULL,
 CHANGE_DT DATE NOT NULL, ORDER_TP VARCHAR(12) NOT NULL,
 BEFORE_PROD_CD VARCHAR(12) NULL, AFTER_PROD_CD VARCHAR(12) NULL,
 KEY IX_HIST_CTRT_DT (CTRT_ID, CHANGE_DT)
) ENGINE=InnoDB;

CREATE TABLE KB_DISCOUNT_INFO (
 DISC_INFO_ID INT PRIMARY KEY, CTRT_ID VARCHAR(12) NOT NULL,
 BILL_YYMM CHAR(6) NOT NULL, FTCR_CD VARCHAR(16) NOT NULL,
 FTCR_VAL VARCHAR(30) NULL, FTCR_CD1 VARCHAR(16) NULL,
 FTCR_VAL1 VARCHAR(30) NULL, FTCR_CD2 VARCHAR(16) NULL,
 FTCR_VAL2 VARCHAR(30) NULL,
 KEY IX_KB_MONTH_CTRT (BILL_YYMM, CTRT_ID),
 KEY IX_KB_CTRT_MONTH (CTRT_ID, BILL_YYMM), KEY IX_KB_CODE (FTCR_CD)
) ENGINE=InnoDB;

CREATE TABLE CHARGE_TEMP (
 CHRG_ID INT PRIMARY KEY, CTRT_ID VARCHAR(12) NOT NULL,
 BILL_YYMM CHAR(6) NOT NULL, BILL_CYCLE CHAR(2) NOT NULL,
 SR_CD VARCHAR(12) NOT NULL, CHRG_AMT DECIMAL(13,2) NOT NULL,
 KEY IX_CHRG_MONTH_CYCLE (BILL_YYMM, BILL_CYCLE),
 KEY IX_CHRG_CTRT_MONTH (CTRT_ID, BILL_YYMM, BILL_CYCLE),
 KEY IX_CHRG_ITEM (SR_CD)
) ENGINE=InnoDB;

CREATE TABLE DISCOUNT_RESULT (
 DISC_RESULT_ID INT PRIMARY KEY, CTRT_ID VARCHAR(12) NOT NULL,
 BILL_YYMM CHAR(6) NOT NULL, FTCR_CD VARCHAR(16) NOT NULL,
 DISC_AMT DECIMAL(13,2) NOT NULL, CALC_STATUS VARCHAR(12) NOT NULL,
 KEY IX_RESULT_MONTH_CTRT (BILL_YYMM, CTRT_ID),
 KEY IX_RESULT_CODE (FTCR_CD)
) ENGINE=InnoDB;

CREATE TABLE BILL (
 BILL_ID INT PRIMARY KEY, CTRT_ID VARCHAR(12) NOT NULL,
 BILL_YYMM CHAR(6) NOT NULL, SR_CD VARCHAR(12) NOT NULL,
 BILL_AMT DECIMAL(13,2) NOT NULL,
 KEY IX_BILL_MONTH_CTRT (BILL_YYMM, CTRT_ID),
 KEY IX_BILL_ITEM (SR_CD)
) ENGINE=InnoDB;

